const e={meta:{title:"POP · El SaaS de los creadores de UEFN"},nav:{features:"Funciones",pricing:"Precios",faq:"FAQ",login:"Iniciar sesión",join:"Unirse a la beta",home:"POP, inicio",lang:"Idioma",search:"Buscar un país"},hero:{announce:"Beta privada abierta a creadores de UEFN",h1a:"Crea en UEFN.",h1b:"Solo o en equipo, sin caos.",subA:"POP es el SaaS que ayuda a los creadores de UEFN de la idea al lanzamiento: ",subB:"tareas de una hora",subC:", Verse conectado a UEFN, pizarra, análisis de mercado y reparto de ingresos.",cta:"Unirse a la lista de espera",see:"Ver las funciones",micro1:"Beta privada",micro2:"Acceso por lista de espera",micro3:"Conectado a UEFN"},marquee:{label:"Funciona con tus herramientas",epic:"API de Fortnite de Epic"},pain:{eyebrow:"El problema",h2a:"Discord, Google Docs, Verse en .txt…",h2b:"y el mapa no avanza.",without:"Sin POP",with:"Con POP",bad:["«¿Quién ha tocado el spawner?»","El Verse pasa por Discord en .txt","Una lista de tareas en un Google Doc","La hoja de ingresos, versión 7","«¿Cuándo salimos al final?»","Construir sin saber si el género funciona"],good:["Cada acción queda registrada y se puede deshacer","Ctrl+S envía el Verse a UEFN","Tareas de una hora, con dependencias","Un extracto claro para cada uno","Hitos y retrasos seguidos automáticamente","Un veredicto por género, con cifras reales"]},feat:{eyebrow:"Funciones",h2:"Todo para crear en UEFN, de la idea al día del lanzamiento.",p:"Lo que ves aquí son las pantallas reales de POP, simplificadas.",items:[{tag:"Tareas y planificación",h:"Tareas de una hora. Una planificación que se cumple.",p:"El generador divide el mapa en tareas de una hora con sus dependencias. La planificación sigue los hitos y avisa de los retrasos, y un asistente integrado resume el día.",pts:["Kanban y dependencias","Hitos y retrasos seguidos","Resumen del día"]},{tag:"Editor Verse",h:"Ctrl+S, y ya está en UEFN.",p:"El Verse se escribe en POP y va directo a tu proyecto: compilación, errores en la línea correcta, sesión de prueba. El asistente explica y corrige, sin servicio externo.",pts:["Compilación en UEFN","Errores en la línea","Correcciones sugeridas"]},{tag:"Organizador",h:"Todos tus dispositivos. Ordenados en tres segundos.",p:"Busca por etiqueta, tipo o carpeta, selecciona veinte y renómbralos, muévelos o duplícalos de una vez. Ctrl+Z deshace. Si UEFN está cerrado, los cambios esperan.",pts:["Búsqueda tag:, type:, carpeta:","Cambios en lote","Todo se puede deshacer"]},{tag:"Pizarra",h:"Dibuja el mapa en equipo.",p:"Notas, formas, flechas, colores, negrita, subrayado: todo lo necesario para plasmar ideas. Votad y convertid las mejores notas en tareas.",pts:["Formato completo","Tiempo real en equipo","Notas → tareas"]},{tag:"Análisis",h:"Sabe qué construir antes de construir.",p:"Qué géneros atraen jugadores, dónde hay hueco, qué mapas despegan desde su salida y qué triunfa en vídeo. Cifras de la API oficial de Epic.",pts:["Veredicto por género","Mapas que funcionan","Tendencias TikTok y Shorts"]},{tag:"Pagos",h:"Cada uno sabe lo que cobra.",p:"Reglas de reparto por porcentaje, fijo o por tarea, importación de ingresos, extracto por persona. Se acabó la hoja perdida en Discord.",pts:["Porcentaje, fijo, por tarea","Importación CSV","Extracto de cada uno"]}],aiB:"¿Ya usas una IA?",aiText:"Conecta Claude, Cursor, Codex u otra IA compatible con MCP: toma una tarea, escribe el Verse, compila y cierra la tarea con una nota. Cada acción queda registrada y se puede deshacer."},stats:[["1 h","por tarea, para avanzar cada día"],["0","servicios de IA externos obligatorios"],["7 días","de estadísticas por mapa, de la API de Epic"],["100 %","de las acciones UEFN se pueden deshacer"]],pricing:{eyebrow:"Precios",h2:"Elige tu plan.",p:"POP está en beta privada: el acceso es por lista de espera. Los precios se aplican en el lanzamiento y te avisaremos antes de cualquier pago.",perMonth:"/ mes",compare:"Comparar planes",unlimited:"Ilimitado",soon:"Pronto",plans:[{name:"Creador",tag:"Para empezar",desc:"Un mapa, un equipo pequeño, lo esencial.",cta:"Unirse a la lista"},{name:"Studio",tag:"El más completo",desc:"Para estudios que lanzan mapas en equipo.",cta:"Unirse a la lista"},{name:"Studio+",tag:"Pronto",desc:"Todo Studio, más POP Forge: la app de escritorio que construye en UEFN.",cta:"Unirse a la lista"}],rows:["Organización","Tareas de una hora, Kanban, dependencias","Asistente integrado (resumen del día, retrasos)","Páginas, pizarra, planificación e hitos","Mapas","Miembros","UEFN","UEFN Link: proyectos sincronizados","Editor Verse conectado (compilación, errores por línea)","Organizador de actores y cambios en lote","IA conectadas (Claude, Cursor, Codex…)","POP Forge: construcción asistida en UEFN","Crecimiento","Análisis de mercado y mapas que funcionan","Tendencias de vídeo TikTok y YouTube Shorts","Intercambio de playtests y día del lanzamiento","Reparto de ingresos y extractos","Discord, GitHub, Lore"]},faq:{eyebrow:"FAQ",h2:"Las preguntas que nos hacen.",items:[["¿Hace falta un PC con Windows?","Para conectar UEFN, sí: UEFN solo funciona en Windows y UEFN Link se ejecuta en ese PC. El resto de POP funciona en cualquier navegador, Mac incluido."],["¿POP publica mi mapa?","No. POP lo prepara todo (revisión previa, playtests, plan del día del lanzamiento), pero la publicación se hace siempre en el portal de creadores de Epic."],["¿POP sirve si creo solo?","Sí. POP sirve tanto a creadores en solitario como a equipos: el plan Creador es gratis para un mapa y puedes invitar a miembros más adelante sin cambiar nada."],["¿Y si quiero usar mi propia IA?","Conecta Claude, Cursor, Codex u otra IA compatible con MCP en «IA conectadas». Puede leer y modificar tus tareas, tu Verse y tus actores UEFN, y cada acción queda registrada y se puede deshacer."],["¿De dónde salen las cifras del análisis?","De la API oficial de Fortnite de Epic: jugadores, pico de jugadores simultáneos, tiempo de juego y retención de cada mapa público, durante 7 días."],["¿Cómo consigo acceso?","POP está en beta privada. Únete a la lista de espera: revisamos las solicitudes una a una y luego te enviamos tu usuario y una contraseña provisional, que cambiarás al iniciar sesión por primera vez."],["¿Cuánto cuesta?","Los precios están más arriba. Se aplican en el lanzamiento de POP; los miembros de la beta reciben aviso antes de cualquier pago."]]},final:{h2a:"Tu próximo mapa",h2b:"empieza aquí.",p:"Únete a la lista de espera: te enviaremos acceso en cuanto haya plaza."},foot:{made:"Hecho por creadores de Fortnite, para creadores de Fortnite.",legal:"Fortnite y UEFN son marcas de Epic Games. POP no está afiliado ni respaldado por Epic Games.",product:"Producto",help:"Ayuda",account:"Cuenta"},mock:{overview:"Resumen",nav:["Resumen","Páginas","Pizarra","Tareas","Editor Verse","Organizador","Mercado"],hello:"Hola Léa, te propongo empezar por #42.",late:"2 tareas con retraso (la más antigua era para el 12 nov.).",mile:"Hito «Beta» en 5 días: quedan 9 tareas, retraso previsto de 1 día.",take:"Tomar",start:"Empezar",unlocks:"desbloquea otras 3 tareas",today:"prevista hoy",waits:"espera #42",todo:"Por hacer",doing:"En curso",done:"Hecho",tasks:["Sistema de puntuación","Decorado de la zona 2","Pantalla final","Playtest interno","Aparición de jugadores","Tormenta"],sent:"enviado a UEFN",err:"Línea 12: int y float no se pueden sumar.",fix:"Corregir: Points += 1",red:"Equipo rojo",selected:"2 seleccionados",rename:"Renombrar",move:"Mover",dup:"Duplicar",s1:"Modo equipos 4v4",s2a:"Jefe final",s2b:"en el centro",s3:"Economía: 1 moneda / eliminación",verdicts:["Buena oportunidad","Popular pero disputado","Saturado","Nicho"],typical:"jugadores / mapa típico",earnings:"Ingresos de octubre",roles:["Código · 40 %","Mapa · 35 %","Música · fijo","Resto"],noTransfer:"POP calcula, no hace ninguna transferencia."},wl:{eyebrow:"Beta privada",title:"Unirse a la lista de espera",intro:"Abrimos POP poco a poco para acompañar a cada creador. Cuéntanos quién eres y te enviaremos tu acceso lo antes posible.",pageIntro:"Durante la beta, el equipo crea las cuentas de POP. Cuéntanos quién eres: en cuanto se apruebe tu acceso, recibirás tu usuario y una contraseña provisional.",invalid:"Este enlace de acceso no es válido, ya se usó o ha caducado. Vuelve a solicitarlo o escribe al equipo de POP.",name:"Nombre o apodo",email:"Correo electrónico",studio:"Estudio",optional:"(opcional)",studioPh:"Nombre del estudio",team:"Tamaño del equipo",teams:["Solo","2 a 3","4 a 10","Más de 10"],exp:"Experiencia",exps:["Principiante en UEFN","Algunos mapas publicados","Creador experimentado","Estudio profesional"],links:"Tus mapas o redes",linksPh:"Códigos de isla, TikTok, YouTube…",msg:"Qué quieres hacer con POP",msgPh:"Ej.: somos 4 en un mapa tycoon y nos perdemos entre Discord y Google Docs.",send:"Solicitar acceso",sending:"Enviando…",nospam:"Sin spam: solo te escribimos para darte acceso.",okTitle:"¡Anotado, gracias!",okText:"Tu solicitud ha llegado al equipo de POP. En cuanto haya una plaza, te enviaremos tu usuario y una contraseña provisional.",alreadyTitle:"Ya estás en la lista.",approvedTitle:"Tu acceso ya está aprobado.",approvedText:"Tu cuenta está lista: el equipo de POP te envía tu usuario y tu contraseña provisional. Si no, escríbenos.",close:"Cerrar"}};export{e as default};
